/* ПЕРЕВОДЧИК (ЯНДЕКС). Переводит выделенные клетки через Translate API v2
   Яндекс Облака.

   Уговор с сервисом (проверено по документации 30.09.2026):
     POST <корень>/translate/v2/translate
       заголовок Authorization: Api-Key <ключ>   (или Bearer <IAM-токен>)
       тело {folderId, texts: [...], targetLanguageCode, sourceLanguageCode?, format}
       ответ {translations: [{text, detectedLanguageCode}]}
     POST <корень>/translate/v2/languages  {folderId} → {languages: [{code, name}]}
     POST <корень>/translate/v2/detect     {folderId, text} → {languageCode}
   Предел сервиса — 10 000 знаков на запрос, поэтому клетки идут порциями.

   Ключ доступа живёт в ХРАНИЛИЩЕ ПЛАГИНА (`тайно`): не в книге и не в файле
   плагина. Книга ходит по рукам, ключ ходить не должен.

   Поле «Сервер» пустое означает обычный адрес Яндекса. Оно нужно там, где
   наружу пускают только через свой прокси, — и там же его видно при
   установке, в списке разрешённых адресов. */

/* ОДИН ПЛАГИН НА ДВА ПРИЛОЖЕНИЯ: доступ к сервису, языки и порции — общие;
   разное только «что переводим и куда кладём». */
const вДокументе = typeof документ !== 'undefined';

const КОРЕНЬ = 'https://translate.api.cloud.yandex.net';
const ЗНАКОВ_В_ЗАПРОСЕ = 9000;      // у сервиса предел 10 000 — берём с запасом
const ТЕКСТОВ_В_ЗАПРОСЕ = 50;

/* Языки, которые нужны чаще всего: список работает и без обращения к сервису. */
const ЯЗЫКИ_СВОИ = [
  ['ru', 'русский'], ['en', 'английский'], ['de', 'немецкий'], ['fr', 'французский'],
  ['es', 'испанский'], ['it', 'итальянский'], ['pt', 'португальский'], ['pl', 'польский'],
  ['uk', 'украинский'], ['be', 'белорусский'], ['kk', 'казахский'], ['uz', 'узбекский'],
  ['az', 'азербайджанский'], ['hy', 'армянский'], ['ka', 'грузинский'], ['tr', 'турецкий'],
  ['zh', 'китайский'], ['ja', 'японский'], ['ko', 'корейский'], ['ar', 'арабский'],
  ['he', 'иврит'], ['hi', 'хинди'], ['cs', 'чешский'], ['sk', 'словацкий'],
  ['sr', 'сербский'], ['bg', 'болгарский'], ['ro', 'румынский'], ['hu', 'венгерский'],
  ['el', 'греческий'], ['nl', 'нидерландский'], ['sv', 'шведский'], ['no', 'норвежский'],
  ['da', 'датский'], ['fi', 'финский'], ['et', 'эстонский'], ['lv', 'латышский'],
  ['lt', 'литовский'], ['vi', 'вьетнамский'], ['th', 'тайский'], ['id', 'индонезийский'],
];
const ПОРУССКИ = {};
for(const [код, имя] of ЯЗЫКИ_СВОИ) ПОРУССКИ[код] = имя;

const подпись = (код, имя) => (ПОРУССКИ[код] || имя || код) + ' (' + код + ')';
const кодИз = строка => { const м = /\(([A-Za-z-]+)\)\s*$/.exec(String(строка || '')); return м ? м[1] : ''; };

/* список языков: свой, а поверх — тот, что прислал сервис (если просили) */
function списки(){
  const сохранённые = хранилище.взять('языки', null);
  const пары = сохранённые && сохранённые.length ? сохранённые : ЯЗЫКИ_СВОИ;
  const подписи = пары.map(([к, и]) => подпись(к, и));
  панель.список('изЯзыка', ['определить сам'].concat(подписи));
  панель.список('вЯзык', подписи);
  return пары;
}

function Старт(){
  панель.поле('каталог', хранилище.взять('каталог', ''));
  панель.поле('ключ', хранилище.взять('ключ', '') ? '••••••••' : '');
  панель.поле('сервер', хранилище.взять('сервер', ''));
  const пары = списки();
  const было = хранилище.взять('вЯзык', 'en');
  панель.поле('вЯзык', подпись(было, (пары.find(п => п[0] === было) || [])[1]));
  панель.поле('изЯзыка', 'определить сам');
  панель.сообщение(хранилище.взять('ключ', '')
    ? 'Доступ запомнен — можно переводить.'
    : 'Нужны ключ и каталог из Яндекс Облака: раздел AI Studio → Translate. Введите их и нажмите «Запомнить доступ».');
}

/* --- доступ ---------------------------------------------------------------- */
function Запомнить(){
  const п = параметры({});
  const ключ = String(п.ключ || '');
  if(ключ && ключ !== '••••••••') хранилище.тайно('ключ', ключ);
  хранилище.положить('каталог', String(п.каталог || ''));
  хранилище.положить('сервер', String(п.сервер || ''));
  панель.поле('ключ', хранилище.взять('ключ', '') ? '••••••••' : '');
  панель.сообщение('Доступ запомнен в этом браузере: ни в книгу, ни в файл плагина он не уйдёт.');
}
function Забыть(){
  хранилище.убрать('ключ'); хранилище.убрать('каталог'); хранилище.убрать('сервер');
  панель.поле('ключ', ''); панель.поле('каталог', ''); панель.поле('сервер', '');
  панель.сообщение('Запомненный доступ убран.');
}

function доступ(п){
  const ключ = String(п.ключ || '') && String(п.ключ) !== '••••••••' ? String(п.ключ) : хранилище.взять('ключ', '');
  const каталог = String(п.каталог || '') || хранилище.взять('каталог', '');
  const корень = (String(п.сервер || '') || хранилище.взять('сервер', '') || КОРЕНЬ).replace(/\/+$/, '');
  return {ключ: ключ, каталог: каталог, корень: корень};
}

/* Один вызов к сервису. Ошибку сервиса показываем его же словами: в ней
   сказано, что не так с ключом или каталогом, а наша догадка была бы хуже. */
async function вызов(д, путь, тело){
  if(!д.ключ) throw new Error('Нет ключа доступа: введите его и нажмите «Запомнить доступ»');
  if(!д.каталог) throw new Error('Нет каталога (folderId): он виден на странице каталога в Яндекс Облаке');
  const о = await запрос(д.корень + путь, {
    метод: 'POST',
    заголовки: {'Content-Type': 'application/json', 'Authorization': 'Api-Key ' + д.ключ},
    тело: JSON.stringify(Object.assign({folderId: д.каталог}, тело)),
    срок: 30000,
  });
  if(!о.ок){
    const сказал = о.тело && (о.тело.message || о.тело.error_message);
    throw new Error('Сервис ответил ' + о.код + (сказал ? ': ' + сказал : '') );
  }
  if(!о.тело) throw new Error('Ответ сервиса не разобрать: ' + String(о.текст || '').slice(0, 120));
  return о.тело;
}

/* --- языки ----------------------------------------------------------------- */
async function Языки(){
  const п = параметры({}), д = доступ(п);
  try {
    const о = await вызов(д, '/translate/v2/languages', {});
    const пары = (о.languages || []).filter(я => я && я.code).map(я => [я.code, я.name || '']);
    if(!пары.length) throw new Error('Сервис вернул пустой список языков');
    пары.sort((a, b) => подпись(a[0], a[1]).localeCompare(подпись(b[0], b[1]), 'ru'));
    хранилище.положить('языки', пары);
    списки();
    панель.сообщение('Языков получено: ' + пары.length);
  } catch(e){ панель.сообщение(e.message); }
}

async function Определить(){
  const п = параметры({}), д = доступ(п);
  const своё = вДокументе
    ? ((документ.выделение || {}).текст || (документ.выделение || {}).абзац || '')
    : (книга.выделение ? String(ячейка(книга.выделение.адрес).значение || '') : '');
  const текст = String(п.текст || '') || своё;
  if(!текст.trim()){ панель.сообщение(вДокументе
    ? 'Нечего определять: введите текст или поставьте курсор в абзац'
    : 'Нечего определять: введите текст или встаньте на клетку с текстом'); return; }
  try {
    const о = await вызов(д, '/translate/v2/detect', {text: текст.slice(0, 1000)});
    const код = о.languageCode || '';
    панель.сообщение(код ? 'Это ' + подпись(код, '') : 'Язык не определился');
  } catch(e){ панель.сообщение(e.message); }
}

/* --- перевод --------------------------------------------------------------- */
/* Порции: у сервиса предел на длину запроса, а у нас может быть тысяча клеток. */
function порции(тексты){
  const из = []; let текущая = [], знаков = 0;
  for(const т of тексты){
    if(текущая.length && (текущая.length >= ТЕКСТОВ_В_ЗАПРОСЕ || знаков + т.length > ЗНАКОВ_В_ЗАПРОСЕ)){
      из.push(текущая); текущая = []; знаков = 0;
    }
    текущая.push(т); знаков += т.length;
  }
  if(текущая.length) из.push(текущая);
  return из;
}

async function перевести(д, тексты, п){
  const тело = {texts: тексты, targetLanguageCode: кодИз(п.вЯзык) || 'en',
                format: п.формат === 'HTML' ? 'HTML' : 'PLAIN_TEXT'};
  const откуда = кодИз(п.изЯзыка);
  if(откуда) тело.sourceLanguageCode = откуда;
  const о = await вызов(д, '/translate/v2/translate', тело);
  const готовые = (о.translations || []).map(т => (т && т.text !== undefined) ? т.text : '');
  if(готовые.length !== тексты.length) throw new Error('Сервис вернул ' + готовые.length + ' переводов на ' + тексты.length + ' строк');
  return готовые;
}

async function Перевести(){
  if(вДокументе) return ПеревестиДок();
  const п = параметры({}), д = доступ(п), в = книга.выделение;
  if(!в){ панель.сообщение('Сначала выделите клетки с текстом'); return; }
  хранилище.положить('вЯзык', кодИз(п.вЯзык) || 'en');
  const л = лист(в.лист);
  let строки;
  try { строки = await л.прочитать(в.область); } catch(e){ панель.сообщение(e.message); return; }

  /* что переводим: только текст, и только непустое */
  const места = [], тексты = [];
  for(let r = 0; r < строки.length; r++) for(let c = 0; c < строки[r].length; c++){
    const з = строки[r][c];
    if(typeof з !== 'string' || !з.trim()) continue;
    if(з.length > ЗНАКОВ_В_ЗАПРОСЕ){ панель.сообщение('Клетка длиннее ' + ЗНАКОВ_В_ЗАПРОСЕ + ' знаков — сервис столько за раз не берёт'); return; }
    места.push([r, c]); тексты.push(з);
  }
  if(!тексты.length){ панель.сообщение('В ' + в.область + ' нет текста — переводить нечего'); return; }

  const части = порции(тексты);
  const готовые = [];
  панель.поле('ход', 0);
  for(let i = 0; i < части.length; i++){
    панель.сообщение('Перевожу: ' + (готовые.length + части[i].length) + ' из ' + тексты.length + '…');
    try { готовые.push.apply(готовые, await перевести(д, части[i], п)); }
    catch(e){ панель.поле('ход', 0); панель.сообщение(e.message); return; }
    панель.поле('ход', (i + 1) / части.length);
  }

  /* куда класть: на место, в соседний столбец или просто показать */
  if(п.куда === 'в журнал'){
    панель.поле('ход', 1);
    панель.сообщение('Перевод:\\n' + готовые.slice(0, 20).join('\\n') + (готовые.length > 20 ? '\\n…' : ''));
    return;
  }
  const вбок = п.куда === 'рядом справа' ? (в.c2 - в.c1 + 1) : 0;
  const новые = строки.map(р => р.slice());
  места.forEach(([r, c], i) => { новые[r][c] = готовые[i]; });
  if(вбок){
    const область = столбецИмя(в.c1 + вбок) + в.r1 + ':' + столбецИмя(в.c2 + вбок) + в.r2;
    /* справа может быть не пусто — спрашиваем, а не затираем молча */
    const было = await л.прочитать(область);
    const занято = было.reduce((с, р) => с + р.filter(з => з !== null && з !== undefined && з !== '').length, 0);
    if(занято && !(await диалог.вопрос('В ' + область + ' занято клеток: ' + занято + '. Переписать их переводом?'))){
      панель.поле('ход', 0); панель.сообщение('Перевод не записан: справа занято'); return;
    }
    л.диапазон(область).записать(новые);
    л.диапазон(область).выделить();
    панель.сообщение('Переведено строк: ' + готовые.length + ' — положил в ' + область);
  } else {
    л.диапазон(в.область).записать(новые);
    панель.сообщение('Переведено клеток: ' + готовые.length + ' в ' + в.область);
  }
  панель.поле('ход', 1);
}

function столбецИмя(с){ let имя = ''; while(с > 0){ const о = (с - 1) % 26; имя = String.fromCharCode(65 + о) + имя; с = (с - о - 1) / 26; } return имя; }

/* --- документ --------------------------------------------------------------
   Переводим выделенные абзацы, а без выделения — весь документ. Кладём на
   место, следом за абзацем (тогда рядом видно оба языка) или просто в журнал.
   Перевод возвращается простым текстом, поэтому «на место» стирает оформление
   внутри абзаца — об этом сказано прямо, до записи. */
async function ПеревестиДок(){
  const п = параметры({}), д = доступ(п);
  хранилище.положить('вЯзык', кодИз(п.вЯзык) || 'en');
  const блоки = документ.блоки, в = документ.выделение || {};
  const где = (в.блок >= 0 && в.есть) ? [в.блок] : блоки.map((б, i) => i);
  const места = [], тексты = [];
  for(const и of где){
    const б = блоки[и]; if(!б || !б.текст.trim()) continue;
    if(б.текст.length > ЗНАКОВ_В_ЗАПРОСЕ){ панель.сообщение('Абзац ' + (и + 1) + ' длиннее ' + ЗНАКОВ_В_ЗАПРОСЕ + ' знаков — сервис столько за раз не берёт'); return; }
    места.push(и); тексты.push(б.текст);
  }
  if(!тексты.length){ панель.сообщение('Переводить нечего: в выделении нет текста'); return; }

  const части = порции(тексты);
  const готовые = [];
  панель.поле('ход', 0);
  for(let i = 0; i < части.length; i++){
    панель.сообщение('Перевожу: ' + (готовые.length + части[i].length) + ' из ' + тексты.length + '…');
    try { готовые.push.apply(готовые, await перевести(д, части[i], п)); }
    catch(e){ панель.поле('ход', 0); панель.сообщение(e.message); return; }
    панель.поле('ход', (i + 1) / части.length);
  }
  if(п.куда === 'в журнал'){
    панель.поле('ход', 1);
    панель.сообщение('Перевод:\n' + готовые.slice(0, 20).join('\n') + (готовые.length > 20 ? '\n…' : ''));
    return;
  }
  const рядом = п.куда === 'рядом справа';          // в документе «рядом» значит «следующим абзацем»
  if(!рядом && !(await диалог.вопрос('Заменить ' + готовые.length + ' абзац(ев) переводом? Оформление внутри абзаца при этом потеряется.'))){
    панель.поле('ход', 0); панель.сообщение('Перевод не записан'); return;
  }
  /* идём с конца: вставки сдвигают номера абзацев ниже места вставки */
  for(let i = места.length - 1; i >= 0; i--){
    const и = места[i], готов = готовые[i];
    if(рядом) документ.вставить(и + 1, '<p>' + эк(готов) + '</p>');
    else документ.правитьБлок(и, {текст: готов});
  }
  документ.перейти(места[0]);
  панель.поле('ход', 1);
  панель.сообщение('Переведено абзацев: ' + готовые.length + (рядом ? ' — положил следом за каждым' : ''));
}
const эк = т => String(т == null ? '' : т).replace(/[&<>]/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;'}[c]));

/* Перевод одной строки из поля — попробовать, ничего не трогая в книге */
async function Проба(){
  const п = параметры({}), д = доступ(п);
  const текст = String(п.текст || '');
  if(!текст.trim()){ панель.сообщение('Введите текст в поле «Проба»'); return; }
  try {
    const готовые = await перевести(д, [текст], п);
    панель.поле('перевод', готовые[0]);
  } catch(e){ панель.сообщение(e.message); }
}

/* Пункт меню на любой клетке с текстом */
async function ИзМеню(){ await Перевести(); }
